#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
PASQAL two-atom zero-point G4 prospective audit — standalone Colab edition.

This single file embeds:
  * pasqal_two_atom_matched_fibre_test.py
  * pasqal_two_atom_q2_prospective_ranking.py
  * pasqal_two_atom_G4_prospective_v3.py

No companion files or passwords are required. Only NumPy and SciPy are used.
In Colab, upload this file and run:
    %run /content/pasqal_two_atom_G4_standalone_colab.py
"""

from __future__ import annotations

import base64
import gzip
import sys
import types

_EMBEDDED = {
    "pasqal_two_atom_matched_fibre_test": "",
    "pasqal_two_atom_q2_prospective_ranking": "",
    "_g4_main": "",
}


def _source(key: str) -> bytes:
    return gzip.decompress(base64.b64decode(_EMBEDDED[key]))


def _install_module(name: str) -> None:
    module = types.ModuleType(name)
    module.__file__ = f"<embedded:{name}>"
    module.__package__ = ""
    sys.modules[name] = module
    code = compile(_source(name), module.__file__, "exec")
    exec(code, module.__dict__)


def main() -> None:
    _install_module("pasqal_two_atom_matched_fibre_test")
    _install_module("pasqal_two_atom_q2_prospective_ranking")
    runtime_file = globals().get("__file__", "<colab-notebook-cell>")
    namespace = {
        "__name__": "__main__",
        "__file__": runtime_file,
        "__package__": None,
    }
    code = compile(
        _source("_g4_main"),
        "<embedded:pasqal_two_atom_G4_prospective_v3>",
        "exec",
    )
    exec(code, namespace)


if __name__ == "__main__":
    main()
